<script lang="ts">
	import UiStatePanel from '#lib/components/UiStatePanel.svelte';
 import {onMount,getContext} from 'svelte';
 import type {I18nState} from '../../../../../lib/i18n/i18n.svelte';
 import {createManagedUsersState} from '../state/managedUsersState.svelte';
 import type {ManagedUser} from '../../domain/entity/UserManagement';
 import {MANAGED_USER_PERMISSION_GROUPS,MANAGED_USER_PERMISSION_KEYS,type ManagedUserPermissionGroup} from '../config/userPermissionGroups';
 const i18n=getContext<I18nState>('i18n'),vm=createManagedUsersState();
 const FUNCTIONS=[['pick','Pick'],['pack','Pack'],['ship','Ship'],['receive','Receive'],['putaway','Put-Away'],['count','Count'],['transfer','Transfer'],['sell','Sell (POS)']] as const;
 const GROUPS=MANAGED_USER_PERMISSION_GROUPS;
 const ALL_KEYS=MANAGED_USER_PERMISSION_KEYS;
 let search=$state(''),formOpen=$state(false),editing=$state<ManagedUser|null>(null);
 let username=$state(''),password=$state(''),fullName=$state(''),role=$state<'ADMIN'|'USER'>('USER');
 let warehouseIds=$state<number[]>([]),functions=$state<string[]>([]),active=$state(true),mustChangePassword=$state(false),pageKeys=$state<string[]>([]);
 let permissionsUser=$state<ManagedUser|null>(null),permissionLoading=$state(false),permissionsReady=$state(true),deleteTarget=$state<ManagedUser|null>(null),localError=$state<string|null>(null);
 const filtered=$derived(vm.users.filter(u=>[u.username,u.fullName,u.role].join(' ').toLowerCase().includes(search.trim().toLowerCase())));
 onMount(()=>{void vm.load();void vm.loadWarehouses();});
 function toggle<T>(a:T[],v:T):T[]{return a.includes(v)?a.filter(x=>x!==v):[...a,v];}
 function reset(){formOpen=false;editing=null;username='';password='';fullName='';role='USER';warehouseIds=[];functions=[];active=true;mustChangePassword=false;pageKeys=[];permissionLoading=false;permissionsReady=true;localError=null;}
 function openCreate(){reset();formOpen=true;}
 async function openEdit(u:ManagedUser){reset();editing=u;username=u.username;fullName=u.fullName;role=u.role;warehouseIds=[...u.warehouseIds];functions=[...u.allowedFunctions];active=u.isActive;mustChangePassword=u.mustChangePassword;formOpen=true;permissionsReady=false;permissionLoading=true;const p=await vm.loadPermissions(u.userId);permissionsReady=!!p;pageKeys=p && p.role === 'USER' && !p.isFullAccess ? [...p.pageKeys] : [];permissionLoading=false;}
 async function save(){
  localError=null;if(editing&&(!permissionsReady||permissionLoading)){localError='No se pudieron cargar los permisos; vuelve a abrir el usuario antes de guardar.';return;}if(!fullName.trim()){localError='El nombre completo es obligatorio';return;}
  if(!editing&&(!username.trim()||!password)){localError='Usuario y contraseña son obligatorios';return;}
  let ok=false;
  let savedUserId=editing?.userId;
  if(editing){ok=await vm.update({userId:editing.userId,fullName:fullName.trim(),role,warehouseIds:[...warehouseIds],allowedFunctions:[...functions],isActive:active,mustChangePassword,password:password||undefined});}
  else {
   const created=await vm.create({username:username.trim(),password,fullName:fullName.trim(),role,warehouseIds:[...warehouseIds],allowedFunctions:[...functions],mustChangePassword});
   ok=!!created;
   if(created){savedUserId=created.userId;editing=created;}
  }
  if(ok&&savedUserId&&role==='USER'){const savedPermissions=await vm.savePermissions(savedUserId,pageKeys);if(!savedPermissions)return;}
  if(ok)reset();
 }
 function toggleGroup(g:ManagedUserPermissionGroup,on:boolean){const keys=g.pages.map(p=>p[0]);pageKeys=on?[...new Set([...pageKeys,...keys])]:pageKeys.filter(k=>!keys.includes(k));}
 async function editPermissions(u:ManagedUser){permissionsUser=u;permissionsReady=false;permissionLoading=true;const p=await vm.loadPermissions(u.userId);permissionsReady=!!p;pageKeys=p && p.role === 'USER' && !p.isFullAccess ? [...p.pageKeys] : [];permissionLoading=false;}
 async function savePerms(){if(permissionsUser&&permissionsReady&&await vm.savePermissions(permissionsUser.userId,pageKeys))permissionsUser=null;}
 async function confirmDelete(){if(deleteTarget&&await vm.remove(deleteTarget.userId))deleteTarget=null;}
 function whName(id:number){const w=vm.warehouses.find(x=>x.warehouseId===id);return w?w.warehouseCode+' · '+w.warehouseName:String(id);}
</script>
<section class="page">
 <header><div><p class="eyebrow">ABELLIS · SMART WMS</p><h1>{i18n.t('Usuarios y permisos')}</h1><p>{i18n.t('Administra cuentas, almacenes asignados y permisos de acceso.')}</p></div><button class="primary" onclick={openCreate}>{i18n.t('Nuevo usuario')}</button></header>
 <div class="toolbar"><label class="search"><span aria-hidden="true">⌕</span><input aria-label="Buscar usuarios" placeholder={i18n.t('Buscar por usuario, nombre o rol…')} bind:value={search}/></label><span>{filtered.length} / {vm.users.length} {i18n.t('usuarios')}</span></div>
 {#if vm.error||localError}<p class="error" role="alert">{localError??vm.error}</p>{/if}
 {#if formOpen}
 <form class="editor" onsubmit={e=>{e.preventDefault();void save();}}>
  <div class="editor-head"><div><p class="eyebrow">{editing?i18n.t('CUENTA EXISTENTE'):i18n.t('NUEVA CUENTA')}</p><h2>{editing?i18n.t('Editar usuario'):i18n.t('Nuevo usuario')}</h2></div><button type="button" onclick={reset}><span aria-hidden="true">×</span></button></div>
  <div class="form-grid">{#if !editing}<label>{i18n.t('Usuario')} *<input required maxlength="50" bind:value={username}/></label>{:else}<label>{i18n.t('Usuario')}<input value={editing.username} disabled/></label>{/if}
   <label>{i18n.t('Nombre completo')} *<input required maxlength="100" bind:value={fullName}/></label>
   <label>{editing?i18n.t('Nueva contraseña (opcional)'):i18n.t('Contraseña')}<input type="password" autocomplete="new-password" bind:value={password} required={!editing}/></label>
   <label>{i18n.t('Rol')}<select bind:value={role}><option value="USER">USER</option><option value="ADMIN">ADMIN</option></select></label></div>
  <section class="section"><div class="section-head"><div><h3>{i18n.t('Almacenes asignados')}</h3><p>{i18n.t('Sin almacenes, el usuario no tendrá acceso a operaciones de almacén.')}</p></div><div class="quick"><button type="button" onclick={()=>warehouseIds=vm.warehouses.map(w=>w.warehouseId)}>{i18n.t('Todos')}</button><button type="button" onclick={()=>warehouseIds=[]}>{i18n.t('Limpiar')}</button></div></div>
   {#if vm.warehouseLoading}<UiStatePanel kind="loading" title={i18n.t('Cargando almacenes')} message={i18n.t('Estamos recuperando los almacenes disponibles para asignación.')} />{:else if !vm.warehouses.length}<UiStatePanel kind="empty" title={i18n.t('Sin almacenes disponibles')} message={i18n.t('No hay almacenes disponibles para asignar.')} />{:else}<div class="checks">{#each vm.warehouses as w (w.warehouseId)}<label class="check"><input type="checkbox" checked={warehouseIds.includes(w.warehouseId)} onchange={()=>warehouseIds=toggle(warehouseIds,w.warehouseId)}/><span><b>{w.warehouseCode}</b><small>{w.warehouseName}</small></span></label>{/each}</div>{/if}
   <small class="muted">{warehouseIds.length} {i18n.t('almacenes seleccionados')}</small>
  </section>
  <section class="section"><div class="section-head"><div><h3>{i18n.t('Acceso a módulos móviles')}</h3><p>{i18n.t('Funciones disponibles en las aplicaciones operativas.')}</p></div><div class="quick"><button type="button" onclick={()=>functions=FUNCTIONS.map(f=>f[0])}>{i18n.t('Todos')}</button><button type="button" onclick={()=>functions=[]}>{i18n.t('Ninguno')}</button></div></div><div class="checks functions">{#each FUNCTIONS as f}<label class="check"><input type="checkbox" checked={functions.includes(f[0])} onchange={()=>functions=toggle(functions,f[0])}/>{f[1]}</label>{/each}</div></section>
  <section class="section"><div class="section-head"><div><h3>{i18n.t('Permisos del administrador web')}</h3><p>{i18n.t('Acceso a páginas y capacidades especiales.')}</p></div><div class="quick"><button type="button" onclick={()=>pageKeys=[...ALL_KEYS]}>{i18n.t('Todos')}</button><button type="button" onclick={()=>pageKeys=[]}>{i18n.t('Ninguno')}</button></div></div>
   {#if role==='ADMIN'}<p class="admin-note"><span aria-hidden="true">✓</span>{i18n.t('ADMIN tiene acceso completo; los permisos individuales no se aplican.')}</p>{:else if permissionLoading}<UiStatePanel kind="loading" title={i18n.t('Cargando permisos')} message={i18n.t('Estamos recuperando los grants del usuario.')} />{:else}<div class="groups">{#each GROUPS as g}<section class:override={g.isOverride} class="group"><div class="group-head"><b>{g.label}</b><span><button type="button" onclick={()=>toggleGroup(g,true)}>{i18n.t('Todos')}</button><button type="button" onclick={()=>toggleGroup(g,false)}>{i18n.t('Ninguno')}</button></span></div>{#each g.pages as p}<label class="check"><input type="checkbox" checked={pageKeys.includes(p[0])} onchange={()=>pageKeys=toggle(pageKeys,p[0])}/>{p[1]}</label>{/each}<small class="muted">{g.pages.filter(p=>pageKeys.includes(p[0])).length}/{g.pages.length}</small></section>{/each}</div>{/if}
  </section>
  {#if editing}<label class="active"><input type="checkbox" bind:checked={active}/><span><b>{i18n.t('Cuenta activa')}</b><small>{i18n.t('Las cuentas inactivas no pueden iniciar sesión.')}</small></span></label>{/if}
  <label class="active"><input type="checkbox" bind:checked={mustChangePassword}/><span><b>{i18n.t('Exigir cambio de contraseña al iniciar sesión')}</b><small>{i18n.t('El usuario deberá cambiar su contraseña antes de acceder a las demás funciones.')}</small></span></label>
  <div class="actions"><button type="button" onclick={reset}>{i18n.t('Cancelar')}</button><button class="primary" type="submit" disabled={vm.saving||vm.warehouseLoading||(!!editing&&(!permissionsReady||permissionLoading))}>{vm.saving?i18n.t('Guardando…'):i18n.t('Guardar usuario')}</button></div>
 </form>{/if}
 {#if permissionsUser}<section class="editor"><div class="editor-head"><div><p class="eyebrow">{i18n.t('AUTORIZACIÓN')}</p><h2>{i18n.t('Permisos de')} {permissionsUser.username}</h2></div><button type="button" onclick={()=>permissionsUser=null}><span aria-hidden="true">×</span></button></div>
  {#if vm.permissions?.isFullAccess}<p class="admin-note">{i18n.t('ADMIN tiene acceso total.')}</p>{:else if permissionLoading}<p>{i18n.t('Cargando permisos…')}</p>{:else}<div class="quick"><button type="button" onclick={()=>pageKeys=[...ALL_KEYS]}>{i18n.t('Todos')}</button><button type="button" onclick={()=>pageKeys=[]}>{i18n.t('Revocar todos')}</button></div><div class="groups">{#each GROUPS as g}<section class:override={g.isOverride} class="group"><div class="group-head"><b>{g.label}</b><span><button type="button" onclick={()=>toggleGroup(g,true)}>{i18n.t('Todos')}</button><button type="button" onclick={()=>toggleGroup(g,false)}>{i18n.t('Ninguno')}</button></span></div>{#each g.pages as p}<label class="check"><input type="checkbox" checked={pageKeys.includes(p[0])} onchange={()=>pageKeys=toggle(pageKeys,p[0])}/>{p[1]}</label>{/each}</section>{/each}</div>{/if}
  <div class="actions"><button type="button" onclick={()=>permissionsUser=null}>{i18n.t('Cerrar')}</button><button class="primary" type="button" disabled={vm.saving||vm.permissions?.isFullAccess||permissionLoading||!permissionsReady} onclick={()=>void savePerms()}>{i18n.t('Guardar permisos')}</button></div></section>{/if}
 {#if vm.loading}<UiStatePanel kind="loading" title={i18n.t('Cargando usuarios')} message={i18n.t('Estamos recuperando las cuentas y sus permisos.')} />{:else}<div class="table-wrap"><table><thead><tr><th>{i18n.t('Usuario')}</th><th>{i18n.t('Nombre')}</th><th>{i18n.t('Rol')}</th><th>{i18n.t('Almacenes')}</th><th>{i18n.t('Estado')}</th><th>{i18n.t('Último acceso')}</th><th>{i18n.t('Acciones')}</th></tr></thead><tbody>
 {#each filtered as u (u.userId)}<tr><td class="mono">{u.username}</td><td>{u.fullName}</td><td><span class:admin={u.role==='ADMIN'} class="pill">{u.role}</span></td><td class="warehouse">{u.warehouseIds.map(whName).join(', ')||'—'}</td><td><span class:inactive={!u.isActive} class="pill status">{u.isActive?i18n.t('Activo'):i18n.t('Inactivo')}</span></td><td>{u.lastLogin?new Date(u.lastLogin).toLocaleString():'—'}</td><td class="row-actions"><button type="button" onclick={()=>void openEdit(u)}>{i18n.t('Editar')}</button><button type="button" onclick={()=>void editPermissions(u)}>{i18n.t('Permisos')}</button><button type="button" class="danger" onclick={()=>deleteTarget=u}>{i18n.t('Eliminar')}</button></td></tr>{:else}<tr><td colspan="7" class="empty">{i18n.t('No hay usuarios que coincidan.')}</td></tr>{/each}
 </tbody></table></div>{/if}
</section>
{#if deleteTarget}<div class="backdrop"><section class="confirm" role="dialog" aria-modal="true"><h2>{i18n.t('Eliminar usuario')}</h2><p>{i18n.t('¿Seguro que deseas eliminar')} <b>{deleteTarget.username}</b>?</p><p class="muted">{i18n.t('Esta acción no se puede deshacer.')}</p><div class="actions"><button onclick={()=>deleteTarget=null}>{i18n.t('Cancelar')}</button><button class="danger-button" disabled={vm.saving} onclick={()=>void confirmDelete()}>{i18n.t('Eliminar')}</button></div></section></div>{/if}
<style>
.page{max-width:88rem;margin:1.4rem auto;padding:0 1.1rem 2rem;color:var(--ink)}header,.editor-head,.section-head,.group-head,.toolbar{display:flex;align-items:center;justify-content:space-between;gap:1rem}header{margin-bottom:1.2rem}h1{margin:0;font:700 1.65rem var(--disp)}header p{color:var(--slate);font-size:.9rem}.eyebrow{font:600 .65rem var(--disp);letter-spacing:.14em;color:var(--slate);margin:0 0 .3rem}.toolbar{margin-bottom:.8rem}.search{display:flex;align-items:center;gap:.55rem;max-width:28rem;width:100%;border:1px solid var(--line);border-radius:9px;padding:0 .7rem;background:var(--card)}.search input{border:0;outline:0;min-height:40px;width:100%;background:transparent;color:var(--ink)}button{border:1px solid var(--line);border-radius:8px;padding:.5rem .75rem;background:var(--card);color:var(--ink);cursor:pointer;font:inherit;font-size:.8rem}.primary{background:var(--navy);color:white;border-color:var(--navy)}button:disabled{opacity:.5;cursor:not-allowed}.danger,.error{color:var(--danger)}.error{padding:.7rem;border:1px solid var(--danger);border-radius:8px}.editor{padding:1.1rem;border:1px solid var(--line);border-radius:13px;background:var(--card);margin:0 0 1rem}.editor-head{margin-bottom:1rem}.editor-head h2{margin:0;font-size:1.15rem}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.85rem}.form-grid>label{display:grid;gap:.35rem;color:var(--slate);font-size:.8rem}.form-grid input,.form-grid select{min-height:40px;border:1px solid var(--line);border-radius:8px;padding:.5rem .65rem;background:var(--card);color:var(--ink);font:inherit}.section{border-top:1px solid var(--line);padding-top:1rem;margin-top:1rem}.section-head{align-items:flex-start;margin-bottom:.65rem}.section-head h3{margin:0;font-size:.94rem}.section-head p{margin:.25rem 0 0;color:var(--slate);font-size:.76rem}.quick{display:flex;gap:.3rem}.quick button,.group-head button{border:0;background:transparent;color:var(--accent);padding:.2rem;font-size:.73rem}.checks{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:.35rem .8rem}.check{display:flex;align-items:center;gap:.55rem;padding:.4rem .5rem;border:1px solid var(--line);border-radius:8px;font-size:.8rem;cursor:pointer}.check input{accent-color:var(--navy)}.check span{display:grid}.check small,.muted{font-size:.72rem;color:var(--slate)}.functions{grid-template-columns:repeat(auto-fit,minmax(130px,1fr))}.groups{display:grid;grid-template-columns:repeat(auto-fit,minmax(245px,1fr));gap:.65rem}.group{padding:.75rem;border:1px solid var(--line);border-radius:9px}.group.override{border-left:3px solid var(--copper)}.group-head{margin-bottom:.45rem}.group-head b{font-size:.72rem;letter-spacing:.06em;text-transform:uppercase}.group .check{border:0;padding:.25rem 0}.group>.muted{display:block;text-align:right}.admin-note{padding:.8rem;border-radius:8px;background:var(--surface);color:var(--slate);font-size:.82rem}.active{display:flex;align-items:center;gap:.6rem;border-top:1px solid var(--line);padding-top:.9rem;margin-top:.9rem}.active span{display:grid}.active small{font-size:.72rem;color:var(--slate)}.actions{display:flex;justify-content:flex-end;gap:.5rem;margin-top:1rem}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:12px;background:var(--card)}table{width:100%;border-collapse:collapse;min-width:880px;font-size:.82rem}th,td{text-align:left;padding:.72rem .8rem;border-bottom:1px solid var(--line);vertical-align:middle}th{color:var(--slate);font-size:.68rem;text-transform:uppercase}tbody tr:hover{background:var(--surface)}.mono{font-family:var(--mono)}.pill{display:inline-flex;padding:.2rem .48rem;border-radius:999px;background:var(--surface);font-size:.7rem}.pill.admin{background:var(--navy);color:white}.status{color:var(--success)}.status.inactive{color:var(--danger)}.warehouse{max-width:22rem;white-space:normal}.row-actions{white-space:nowrap}.row-actions button{margin-right:.2rem}.empty,.loading{text-align:center;padding:2rem;color:var(--slate)}.backdrop{position:fixed;inset:0;background:#10182780;display:grid;place-items:center;padding:1rem;z-index:100}.confirm{width:min(28rem,100%);padding:1.2rem;border:1px solid var(--line);border-radius:13px;background:var(--card);box-shadow:0 18px 60px #0005}.confirm h2{margin:0 0 .8rem;font-size:1.1rem}.confirm p{font-size:.85rem}.danger-button{background:var(--danger);color:white;border-color:var(--danger)}@media(max-width:650px){header,.section-head{align-items:flex-start;flex-direction:column}.form-grid{grid-template-columns:1fr}.toolbar{align-items:flex-start;flex-direction:column}.editor{padding:.85rem}}
</style>